  state = {
    "text": "outer",
    "isShowDialog": false,
    "name": ""
  }
  componentDidMount() {
    console.log('did mount');
  }
  componentWillUnmount() {
    console.log('will unmount');
  }
  testFunc() {
    console.log('test func');
  }
  async onClick() {

    console.log(this.state.username);
    this.setState({
      isShowDialog: true
    });

    const url = 'http://localhost:8888/api/auth/login';

    const data = {
      username: 'yourUsername', // 替换为实际的用户名
      password: 'yourPassword'  // 替换为实际的密码
    };

    fetch(url, {
